/*
 * KOYODA's display content is authored in a logical 466x466 coordinate space
 * and rotated 90 degrees as a whole for the physical panel.  Put the notice
 * image inside its own transparent 466x466 layer and rotate that parent in the
 * same way as Battery/Wi-Fi/Volume.
 *
 * That keeps the 3-bar shape upright and places it at logical top-right.
 */
lv_obj_t *koyoda_listening_notice_create(lv_obj_t *screen)
{
    if (screen == NULL)
    {
        return NULL;
    }

    lv_obj_t *layer = lv_obj_create(screen);
    lv_obj_set_size(layer, 466, 466);
    lv_obj_center(layer);

    lv_obj_set_style_bg_opa(layer, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(layer, 0, 0);
    lv_obj_set_style_outline_width(layer, 0, 0);
    lv_obj_set_style_shadow_width(layer, 0, 0);
    lv_obj_set_style_pad_all(layer, 0, 0);
    lv_obj_set_style_radius(layer, 0, 0);

    lv_obj_clear_flag(layer, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_clear_flag(layer, LV_OBJ_FLAG_CLICKABLE);

    lv_obj_set_style_transform_pivot_x(layer, 233, 0);
    lv_obj_set_style_transform_pivot_y(layer, 233, 0);
    lv_obj_set_style_transform_rotation(layer, 900, 0);

    lv_obj_t *img = lv_image_create(layer);
    lv_image_set_src(img, &koyoda_listening_notice_bars);

    /*
     * Position derived directly from the user's reference, scaled from
     * 1254x1254 to KOYODA's 466x466 logical canvas.
     */
    lv_obj_set_pos(img, 361, 26);
    lv_obj_clear_flag(img, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_clear_flag(img, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(img, LV_OBJ_FLAG_HIDDEN);

    return img;
}
